# Sources des définitions : dossier_sources.json (relu le 14 octobre 2026).
def cim(c, n, full, d, ref=None):
    return (c, [(c.split('.')[0], 'catégorie « Purpura et autres affections hémorragiques » de la CIM-10-GM'), ('.' + c.split('.')[1], 'sous-code ' + c.split('.')[1])], full, d, ref)
